WITH fixes(slug,pos,why) AS (VALUES ('contabilidade-balanco-patrimonial-estrutura',3,'Correto. Ações em tesouraria são ações da própria companhia recompradas e aparecem como dedução do patrimônio líquido, não como ativo.'),
('contabilidade-cebraspe-sefaz-acre-2024-contador',2,'Correto. Pelo CPC 16, os estoques são mensurados pelo menor valor entre custo e valor realizável líquido; isso evita registrar estoque acima do valor recuperável na venda.'),
('contabilidade-dre-dfc-dva-lei-6404',3,'Correto. O art. 187 da Lei 6.404/1976 prevê a apresentação da receita líquida, do custo das mercadorias e serviços vendidos e do lucro bruto na DRE.'),
('contabilidade-dre-dfc-dva-lei-6404',4,'Correto. A Demonstração do Valor Adicionado evidencia a riqueza gerada e como foi distribuída entre empregados, governo, financiadores e proprietários; veja o art. 188, II, da Lei 6.404/1976.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',5,'Correto. Pelo CPC 02, moeda funcional é a moeda do ambiente econômico principal no qual a entidade opera, não necessariamente a moeda usada para apresentar demonstrações.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',11,'Correto. Matéria-prima consumida = estoque inicial + compras − estoque final. Aplicando os valores: R$ 3.000 + R$ 11.000 − R$ 5.000 = R$ 9.000.'),
('contabilidade-gabriel-rabelo-exemplos-cfc-2020-2',12,'Correto. Margem de contribuição unitária = preço de venda − custo variável unitário. Logo, R$ 600 − R$ 200 = R$ 400 por unidade.'),
('contabilidade-notas-explicativas-grande-porte-avp',4,'Correto. O art. 183, VIII, da Lei 6.404/1976 prevê ajuste a valor presente dos elementos do ativo decorrentes de operações de longo prazo; para os demais, quando houver efeito relevante.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;